// Native↔WASM byte-exact parity, size and performance gates for
// browser-owned-listing slice 03 (specs/browser-owned-listing/slices/03-core-wasm.md,
// the judgment gate). Every op runs through the compiled `listing-core-wasm`
// artifact and is compared against the exact same JSON `listing-core`'s
// native tests pinned (`fixtures/listing/core-ops/**`, generated by slice 02;
// `rust/crates/listing-core-wasm/tests/fixtures/{ambient,synthetic}/**`, generated
// by this slice — see those crates' test files for how, and why they exist).
//
// "Byte-exact" here means: parse both sides as JSON and assert deep
// structural equality on the fields the native golden actually pinned (02's
// own golden tests hand-pick fields into ad hoc `json!` objects rather than
// serializing whole `EditOutcome`/`Edited` values — see
// `rust/crates/listing-core-wasm/src/dispatch.rs`'s `edited_json` doc comment) —
// not a literal byte-for-byte file comparison, which would only prove two
// JSON *serializers* format alike, not that the two *rule engines* agree.
import assert from "node:assert/strict"
import { readdirSync, readFileSync } from "node:fs"
import test from "node:test"

import { createListingCore, ListingCoreError, type ListingCore } from "../src/listing-core/wasm"
import type {
  CardPayload,
  CategorySchemaSnapshot,
  EditInput,
  LeanRow,
  ListingFieldEditor,
  RecordRenderInput,
  SearchMaterialEntry,
  ValidateVariantGroupInput,
  VariantProblem,
  WorkflowCategoryDraft,
  WorkflowDraftValue,
} from "../src/listing-core/types"

const wasmUrl = new URL("../../wasm/dist/browser/listing-state.wasm", import.meta.url)
const ambientDir = new URL("../../rust/crates/listing-core-wasm/tests/fixtures/ambient/", import.meta.url)
const syntheticDir = new URL("../../rust/crates/listing-core-wasm/tests/fixtures/synthetic/", import.meta.url)
const goldenDir = new URL("../../fixtures/listing/core-ops/", import.meta.url)

function readJson<T>(url: URL): T {
  return JSON.parse(readFileSync(url, "utf8")) as T
}

/** Missing committed WASM must fail instead of invoking a Rust build in CI. */
async function listingCore(): Promise<{ core: ListingCore; wasmBytes: Buffer }> {
  const wasmBytes = readFileSync(wasmUrl)
  // Deterministic, not cryptographically random: a parity/perf test must be
  // reproducible. None of slice 02's golden cases mint a new complex-item id
  // (only `edit_row`'s `ensure_complex_item_ids` calls `ctx.ids`, and none of
  // the golden/synthetic drafts touch a complex field), so this generator is
  // never on the byte-exact comparison path — see `rust/crates/listing-core-wasm/src/ids.rs`.
  let counter = 1n
  const imports = {
    env: {
      fill_random(ptr: number, len: number) {
        const memory = (instance.exports as unknown as { memory: WebAssembly.Memory }).memory
        const bytes = new Uint8Array(memory.buffer, ptr, len)
        const value = counter++
        const view = new DataView(new ArrayBuffer(16))
        view.setBigUint64(8, value)
        bytes.set(new Uint8Array(view.buffer).subarray(16 - len))
      },
    },
  }
  const { instance } = await WebAssembly.instantiate(wasmBytes, imports)
  return { core: createListingCore(instance.exports), wasmBytes }
}

// ---- Ambient fixtures (the schema/card slice 02's golden tests fixed as
// ambient context, not part of any one case's `.input.json` — see
// `rust/crates/listing-core-wasm/tests/golden_fixture_export.rs`) -----------------

const goldenCoreOpsSchema = readJson<CategorySchemaSnapshot>(new URL("golden-core-ops-schema.json", ambientDir))
const goldenCoreOpsSearchMaterials = readJson<SearchMaterialEntry[]>(
  new URL("golden-core-ops-search-materials.json", ambientDir),
)
const goldenCardDefault = readJson<CardPayload>(new URL("golden-card-default.json", ambientDir))
const decorativeWallArtSchema = readJson<CategorySchemaSnapshot>(new URL("decorative-wall-art-schema.json", ambientDir))

// ---- Op 18: the Cloud/browser grouping contract ----------------------------

/** The same file Cloud's `schema_builder` test reads, with the same expected
 * `problems` list. A divergence between the compiled WASM rules and Cloud's
 * fails here, in the artifact the browser actually ships. */
const variantGroupParity = readJson<ValidateVariantGroupInput & { problems: VariantProblem[] }>(
  new URL("../../fixtures/listing/variant-group-parity.json", import.meta.url),
)

// ---- Per-op parity comparisons ---------------------------------------------

let core: ListingCore
let goldenCoreOpsHandle: number
let decorativeWallArtHandle: number

test.before(async () => {
  ;({ core } = await listingCore())
  goldenCoreOpsHandle = core.loadSchema({ snapshot: goldenCoreOpsSchema, searchMaterials: goldenCoreOpsSearchMaterials })
  decorativeWallArtHandle = core.loadSchema({ snapshot: decorativeWallArtSchema })
})

test.after(() => {
  core.dropSchema(goldenCoreOpsHandle)
  core.dropSchema(decorativeWallArtHandle)
})

/** Op 18: the compiled artifact's problem list must equal the one Cloud's Rust
 * test reads from the same file — and must equal it without a schema handle,
 * because the rule is about the current category material in the body. */
test("validateVariantGroup reproduces Cloud's problem list for the shared fixture", () => {
  const input = { fields: variantGroupParity.fields, group: variantGroupParity.group }
  assert.deepStrictEqual(core.validateVariantGroup(input), variantGroupParity.problems)
  // No handle is needed at all: op 18 carries its material in the body.
  assert.deepStrictEqual(core.validateVariantGroup(input), core.validateVariantGroup(input))
})

/** The unknown state is not "no dimensions": material whose Seller attributes
 * never carried `is_aspect` refuses the grouping instead of passing it. This
 * is the browser half of the cache-refresh contract — a workbench holding a
 * stale payload asks for a refresh rather than sending. */
test("validateVariantGroup refuses material that predates aspect metadata", () => {
  const fields = (variantGroupParity.fields as { attribute_id?: string }[]).map((field) => {
    const { aspect: _dropped, ...rest } = field as { aspect?: boolean }
    void _dropped
    return rest
  })
  assert.deepStrictEqual(
    core.validateVariantGroup({ fields, group: variantGroupParity.group }),
    [
      {
        code: { platform: "ozon", stage: "preview", code: "variant_metadata_unknown" },
        member_id: null,
        field_key: null,
      },
    ],
  )
})

/** Counts every case this file compares, per op, for the report the slice's
 * verification gate asks for ("golden/dev-sample comparison count"). */
const tally: Record<string, number> = {}
function record(op: string) {
  tally[op] = (tally[op] ?? 0) + 1
}

test("seedRow matches all 4 golden cases byte-exact", () => {
  const dir = new URL("seed_row/", goldenDir)
  for (const file of readdirSync(dir).filter((name) => name.endsWith(".input.json"))) {
    const caseName = file.replace(".input.json", "")
    const input = readJson<{ card: CardPayload; source: LeanRow["source"]; suppliedDraft?: WorkflowCategoryDraft }>(
      new URL(file, dir),
    )
    const golden = readJson<LeanRow>(new URL(`${caseName}.output.json`, dir))
    const output = core.seedRow(goldenCoreOpsHandle, { ...input, nowMs: 1_700_000_000_000 })
    assert.deepStrictEqual(output, golden, `seed_row/${caseName}`)
    record("seedRow")
  }
})

test("editRow matches all 3 golden cases byte-exact", () => {
  const dir = new URL("edit_row/", goldenDir)
  const cases: {
    case: string
    nowMs: number
    edit: (input: unknown) => EditInput
    compare: (output: ReturnType<ListingCore["editRow"]>, golden: Record<string, unknown>) => void
  }[] = [
    {
      case: "clear-generated-content-keeps-identity",
      nowMs: 1_700_000_000_100,
      edit: () => ({ kind: "clearGeneratedContent" }),
      compare: (output, golden) => {
        assert.deepStrictEqual(output.row, golden.row, "row")
        assert.equal(output.fact, golden.fact, "fact")
        assert.deepStrictEqual(output.invalidation, golden.invalidation, "invalidation")
        assert.deepStrictEqual(output.stored, golden.stored, "stored")
      },
    },
    {
      case: "truncated-dictionary-search-material",
      nowMs: 1_700_000_000_200,
      edit: (input) => ({
        kind: "draft",
        changes: {},
        draft: (input as { draft: WorkflowCategoryDraft }).draft,
        light: false,
        storeMoved: false,
      }),
      compare: (output, golden) => {
        assert.deepStrictEqual(output.row, golden.row, "row")
        assert.equal(output.fact, golden.fact, "fact")
        assert.deepStrictEqual(output.issues, golden.issues, "issues")
      },
    },
    {
      case: "store-move-with-manual-field",
      nowMs: 1_700_000_000_300,
      edit: (input) => ({
        kind: "draft",
        changes: {},
        draft: (input as { draft: WorkflowCategoryDraft }).draft,
        light: false,
        storeMoved: true,
      }),
      compare: (output, golden) => {
        assert.deepStrictEqual(output.invalidation, golden.invalidation, "invalidation")
        assert.equal(output.fact, golden.fact, "fact")
      },
    },
  ]
  for (const { case: caseName, nowMs, edit, compare } of cases) {
    const input = readJson<Record<string, unknown>>(new URL(`${caseName}.input.json`, dir))
    // Case 1's `.input.json` *is* the bare `LeanRow`; cases 2/3 nest it at `.row`.
    const row = (("row" in input ? input.row : input) as LeanRow)
    const golden = readJson<Record<string, unknown>>(new URL(`${caseName}.output.json`, dir))
    const output = core.editRow(goldenCoreOpsHandle, { card: goldenCardDefault, nowMs, row, edit: edit(input) })
    compare(output, golden)
    record("editRow")
  }
})

