test("revalidate matches its golden case byte-exact", () => {
  const dir = new URL("revalidate/", goldenDir)
  const row = readJson<LeanRow>(new URL("complete-draft-passes.input.json", dir))
  const golden = readJson<Record<string, unknown>>(new URL("complete-draft-passes.output.json", dir))
  const output = core.revalidate(decorativeWallArtHandle, {
    card: goldenCardDefault,
    nowMs: 1_700_000_000_600,
    row,
  })
  assert.deepStrictEqual(output.row, golden.row, "row")
  assert.equal(output.fact, golden.fact, "fact")
  assert.equal(output.contentReady, golden.contentReady, "contentReady")
  assert.equal(output.evidence?.digest ?? null, golden.evidenceDigest, "evidenceDigest")
  record("revalidate")

  // op 6 (`recordUpload`) is byte-identical composition, not a distinct rule
  // — see `rust/crates/listing-core-wasm/src/dispatch.rs`'s module docs.
  const recordUploadOutput = core.recordUpload(decorativeWallArtHandle, { card: goldenCardDefault, nowMs: 1_700_000_000_600, row })
  assert.deepStrictEqual(recordUploadOutput, output, "recordUpload must be byte-identical to revalidate on the same input")
  record("recordUpload")
})

