test("submitDraft (op 9) reconstructs a LeanRow from the Card's category, no schema handle needed", () => {
  const seedFixture = readJson<{ card: CardPayload }>(
    new URL("complex-field-ordering.input.json", new URL("seed_row/", goldenDir)),
  )
  const row = core.submitDraft({
    draft: {
      rowId: "row-submit-draft-parity",
      schemaRevision: "wasm-parity-v1",
      sourceFileName: "draft.psd",
      draft: { values: {}, complex_values: [] },
    },
    card: seedFixture.card,
  })
  assert.equal(row.categoryKey, seedFixture.card.categoryKey)
  assert.equal(row.descriptionCategoryId, seedFixture.card.descriptionCategoryId)
  assert.equal(row.typeId, seedFixture.card.typeId)
  assert.equal(row.schemaRevision, "wasm-parity-v1")
  assert.equal(row.source.fileName, "draft.psd")
  assert.equal(row.normalizedSnapshot, null)
  assert.deepEqual(row.validationIssues, [])
  record("submitDraft")
})

test("submitDraft (op 9) with a malformed body is CORE_DECODE, not a trap", () => {
  assert.throws(
    () => core.submitDraft({ draft: {} } as never),
    (error: unknown) => error instanceof ListingCoreError && error.code === "CORE_DECODE",
  )
})

test("client.ts's Promise wrapper (`ListingCoreClient`) agrees with the direct sync core", async () => {
  const { ListingCoreClient } = await import("../src/listing-core/client")
  const client = new ListingCoreClient(readFileSync(wasmUrl))
  const handle = await client.loadSchema({ snapshot: goldenCoreOpsSchema, searchMaterials: goldenCoreOpsSearchMaterials })
  try {
    const dir = new URL("seed_row/", goldenDir)
    const input = readJson<{ card: CardPayload; source: LeanRow["source"]; suppliedDraft?: WorkflowCategoryDraft }>(
      new URL("chinese-name-and-price-float-text.input.json", dir),
    )
    const viaClient = await client.seedRow(handle, { ...input, nowMs: 1_700_000_000_000 })
    const viaCore = core.seedRow(goldenCoreOpsHandle, { ...input, nowMs: 1_700_000_000_000 })
    assert.deepStrictEqual(viaClient, viaCore, "ListingCoreClient must not alter what the sync core returns")
  } finally {
    await client.dropSchema(handle)
  }
})

// ---- Synthetic batch: a larger native↔WASM sample than the 12 golden cases
// (slice 03's verification gate: "另拿开发库里现有的行 payload 批量跑 native
// 与 wasm...dev 库行数不足就用金标生成器扩样" — see
// `rust/crates/listing-core-wasm/tests/fixtures_synthetic_export.rs` for why this
// worktree has no reachable dev-database rows and what stands in instead). --

test("seedRow + revalidate match the 50-row synthetic batch byte-exact", () => {
  const seedDir = new URL("seed_row/", syntheticDir)
  const revalidateDir = new URL("revalidate/", syntheticDir)
  const cases = readdirSync(seedDir).filter((name) => name.endsWith(".input.json")).map((name) => name.replace(".input.json", ""))
  assert.ok(cases.length >= 50, `expected at least 50 synthetic cases, found ${cases.length}`)
  for (const caseName of cases) {
    // `rust/crates/listing-core-wasm/tests/fixtures_synthetic_export.rs` pins
    // `now_ms: 1_700_000_100_000 + index`, one index per `syn-NNN` case.
    const index = Number.parseInt(caseName.replace("syn-", ""), 10)
    const nowMs = 1_700_000_100_000 + index
    const seedInput = readJson<{ card: CardPayload; source: LeanRow["source"]; suppliedDraft: WorkflowCategoryDraft }>(
      new URL(`${caseName}.input.json`, seedDir),
    )
    const seedGolden = readJson<LeanRow>(new URL(`${caseName}.output.json`, seedDir))
    const seeded = core.seedRow(decorativeWallArtHandle, { ...seedInput, nowMs })
    assert.deepStrictEqual(seeded, seedGolden, `synthetic seed_row/${caseName}`)
    record("synthetic.seedRow")

    const revalidateInput = readJson<LeanRow>(new URL(`${caseName}.input.json`, revalidateDir))
    const revalidateGolden = readJson<Record<string, unknown>>(new URL(`${caseName}.output.json`, revalidateDir))
    const revalidated = core.revalidate(decorativeWallArtHandle, {
      card: seedInput.card,
      nowMs,
      row: revalidateInput,
    })
    assert.deepStrictEqual(revalidated.row, revalidateGolden.row, `synthetic revalidate/${caseName} row`)
    assert.equal(revalidated.fact, revalidateGolden.fact, `synthetic revalidate/${caseName} fact`)
    assert.equal(
      revalidated.evidence?.digest ?? null,
      revalidateGolden.evidenceDigest,
      `synthetic revalidate/${caseName} evidenceDigest`,
    )
    record("synthetic.revalidate")
  }
})

test("parity report: per-op golden/synthetic comparison counts", () => {
  const total = Object.values(tally).reduce((sum, count) => sum + count, 0)
  console.log(`\nlisting-core-wasm native↔WASM parity — ${total} comparisons:`)
  for (const [op, count] of Object.entries(tally).sort()) console.log(`  ${op}: ${count}`)
  assert.ok(total >= 12 + 100, `expected at least 112 comparisons (12 golden + 100 synthetic), got ${total}`)
})

// ---- Browser module: export surface and size gate --------------------------
//
// `wasm/dist/browser/listing-state.wasm` is the one committed browser module:
// the `--features browser` build of `listing-core-wasm`, shared by the app and
// the server's committed counterpart. The feature drops `snapshot_from_fields`
// (the server schema snapshot, which needs a host-supplied field cache), so the
// browser module exports strictly less than `wasm/dist/server/listing-core.wasm`.
// Both assertions below are exact: a superset means the wrong build was
// committed, and the app would download bytes it never calls.
test("the browser module exports send_transition and not snapshot_from_fields", async () => {
  const { wasmBytes } = await listingCore()
  const exported = WebAssembly.Module.exports(new WebAssembly.Module(new Uint8Array(wasmBytes))).map((entry) => entry.name)
  assert.ok(exported.includes("send_transition"), `browser module must export send_transition, got: ${exported.join(", ")}`)
  assert.ok(!exported.includes("snapshot_from_fields"), `browser module must not export snapshot_from_fields, got: ${exported.join(", ")}`)
})

// Upstream gates the browser module at 1.5 MiB. This tree's `listing-core-wasm`
// carries one export upstream does not: `send_transition` (the browser send
// state machine in src/send_state.rs). The export-surface test above keeps the
// server-only `snapshot_from_fields` out of this artifact, so the gate is the
// upstream 1.5 MiB rather than a raised one.
const WASM_SIZE_LIMIT = 1.5 * 1024 * 1024

test("wasm artifact size is at or under 1.5 MiB", async () => {
  const { wasmBytes } = await listingCore()
  const limit = WASM_SIZE_LIMIT
  console.log(`\nlisting-state.wasm size: ${wasmBytes.length} bytes (${(wasmBytes.length / 1024 / 1024).toFixed(3)} MiB), limit ${limit} bytes`)
  assert.ok(wasmBytes.length <= limit, `wasm artifact is ${wasmBytes.length} bytes, over the 1.5 MiB (${limit} byte) limit`)
})

// ---- Performance gates (first run establishes the baseline the numbers
// below are pinned to; see this slice's "完成" section for the measured
// numbers this repository's CI machine produced). ---------------------------

function percentile(sortedMs: number[], p: number): number {
  const index = Math.min(sortedMs.length - 1, Math.floor((p / 100) * sortedMs.length))
  return sortedMs[index]!
}

test("performance: 1000-row revalidate completes in <= 300ms", () => {
  const baseRow = readJson<LeanRow>(new URL("complete-draft-passes.input.json", new URL("revalidate/", goldenDir)))
  const rows: LeanRow[] = Array.from({ length: 1000 }, (_, index) => ({
    ...baseRow,
    source: { ...baseRow.source, sha256: `sha256:perf-${index}` },
  }))
  const start = performance.now()
  for (const row of rows) {
    core.revalidate(decorativeWallArtHandle, { card: goldenCardDefault, nowMs: 1_700_000_200_000, row })
  }
  const elapsedMs = performance.now() - start
  console.log(`\n1000-row revalidate: ${elapsedMs.toFixed(2)}ms (gate: <= 300ms)`)
  assert.ok(elapsedMs <= 300, `1000-row revalidate took ${elapsedMs.toFixed(2)}ms, over the 300ms gate`)
})

test("performance: editRow p95 latency is <= 5ms", () => {
  const dir = new URL("edit_row/", goldenDir)
  const input = readJson<{ row: LeanRow; draft: WorkflowCategoryDraft }>(
    new URL("truncated-dictionary-search-material.input.json", dir),
  )
  const samples: number[] = []
  const iterations = 300
  for (let i = 0; i < iterations; i++) {
    const start = performance.now()
    core.editRow(goldenCoreOpsHandle, {
      card: goldenCardDefault,
      nowMs: 1_700_000_300_000 + i,
      row: input.row,
      edit: { kind: "draft", changes: {}, draft: input.draft, light: false, storeMoved: false },
    })
    samples.push(performance.now() - start)
  }
  samples.sort((a, b) => a - b)
  const p95 = percentile(samples, 95)
  console.log(`\neditRow p95 over ${iterations} calls: ${p95.toFixed(3)}ms (gate: <= 5ms)`)
  assert.ok(p95 <= 5, `editRow p95 is ${p95.toFixed(3)}ms, over the 5ms gate`)
})

test("performance: schema_load for the largest real category schema is <= 200ms", async () => {
  // The largest schema this worktree can reach: `catalog_schema_cache` in the
  // dev Postgres (`podhub-dev-postgres-1`, port 5443) held 3 rows; category
  // 41777465/93040 (zh_hans) is the biggest at 62 fields. Its cached payload
  // is Cloud's pre-normalization Ozon wire shape (`columns_json`), not
  // `ListingFieldDefinition` JSON (`schema_builder.rs` does that conversion,
  // pulling in dictionary options separately) — reverse-engineering that
  // normalization is out of this slice's scope and risks a subtly wrong
  // schema for what is a parsing-*performance* gate, not a parity one. This
  // fixture carries the same 62 real field keys/labels/editors from that
  // category (`web/tests/fixtures/listing-core-perf-schema-fields.json`,
  // extracted once) in the correct `ListingFieldDefinition` shape instead —
  // real field content, synthesized structure, at the real size.
  const { core: freshCore } = await listingCore()
  const fields = readJson<{ key: string; label: string; group: string; editor: string; required: boolean }[]>(
    new URL("fixtures/listing-core-perf-schema-fields.json", import.meta.url),
  )
  assert.equal(fields.length, 62, "the perf schema fixture must carry all 62 real fields it was extracted with")
  const snapshot: CategorySchemaSnapshot = {
    category_key: "perf-largest-real-category",
    label: "性能基准：dev 库最大真实类目（62 字段）",
    description_category_id: 41_777_465,
    type_id: 93_040,
    schema_revision: "perf-v1",
    recipe_id: 0,
    recipe_revision: 1,
    catalog_schema_version: 1,
    fields: fields.map((field) => ({
      key: field.key,
      label: field.label,
      group: field.group,
      editor: field.editor,
      required: field.required,
      constraints: { collection: false, max_value_count: null, dictionary_id: null },
      attribute_id: null,
      complex_id: null,
      description: "",
      raw_type: null,
      read_only: false,
      complex_group_collection: false,
      options: [],
      options_truncated: false,
    })),
  }
  const start = performance.now()
  const handle = freshCore.loadSchema({ snapshot })
  const elapsedMs = performance.now() - start
  console.log(`\nschema_load (62 real fields): ${elapsedMs.toFixed(3)}ms (gate: <= 200ms)`)
  freshCore.dropSchema(handle)
  assert.ok(elapsedMs <= 200, `schema_load took ${elapsedMs.toFixed(3)}ms, over the 200ms gate`)
})
